function slugify(text: string): string {
  return text.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
}

// ---------------------------------------------------------------------------
// 4. Precompiled In-Memory Index of Places
// ---------------------------------------------------------------------------
export const ALL_WORLD_PLACES: WorldPlace[] = [
  // 1. Countries
  ...WORLD_COUNTRIES.map((c) => ({
    name: c.name,
    country: c.name,
    continent: c.continent,
    iso2: c.iso2,
    flagUrl: getFlagUrl(c.iso2),
    isCity: false,
    slug: slugify(c.name),
  })),

  // 2. Cities
  ...WORLD_CITIES.map((c) => ({
    name: c.city === c.country ? c.city : `${c.city}, ${c.country}`,
    cityName: c.city,
    country: c.country,
    continent: c.continent,
    iso2: c.iso2,
    flagUrl: getFlagUrl(c.iso2),
    isCity: true,
    slug: slugify(`${c.city}-${c.country}`),
  })),

  // 3. Airports
  ...WORLD_AIRPORTS.map((a) => ({
    name: `${a.city} (${a.iata}) - ${a.name}, ${a.country}`,
    cityName: a.city,
    country: a.country,
    continent: a.continent,
    iso2: a.iso2,
    flagUrl: getFlagUrl(a.iso2),
    isCity: false,
    isAirport: true,
    iata: a.iata,
    airportName: a.name,
    slug: slugify(`airport-${a.iata}-${a.city}`),
  })),
];

/**
 * Fast prefix & substring matching across countries, cities, and international airports.
 */
export function searchWorldPlaces(query: string, limit = 30): WorldPlace[] {
  const q = (query || '').toLowerCase().trim();
  if (!q) return [];

  const iataMatches: WorldPlace[] = [];
  const exactMatches: WorldPlace[] = [];
  const prefixMatches: WorldPlace[] = [];
  const containsMatches: WorldPlace[] = [];

  for (const p of ALL_WORLD_PLACES) {
    const iataLower = (p.iata || '').toLowerCase();
    const nameLower = p.name.toLowerCase();
    const cityLower = (p.cityName || '').toLowerCase();
    const countryLower = p.country.toLowerCase();
    const airportLower = (p.airportName || '').toLowerCase();

    // 1. Exact IATA code match gets highest priority (e.g. "DAC", "DXB", "LHR", "JFK")
    if (iataLower && iataLower === q) {
      iataMatches.push(p);
      continue;
    }

    // 2. Exact city or country match
    if (nameLower === q || cityLower === q || countryLower === q) {
      exactMatches.push(p);
    } else if (
      (iataLower && iataLower.startsWith(q)) ||
      nameLower.startsWith(q) ||
      cityLower.startsWith(q) ||
      countryLower.startsWith(q) ||
      (airportLower && airportLower.startsWith(q))
    ) {
      prefixMatches.push(p);
    } else if (
      nameLower.includes(q) ||
      cityLower.includes(q) ||
      countryLower.includes(q) ||
      (airportLower && airportLower.includes(q))
    ) {
      containsMatches.push(p);
    }
  }

  const results = [...iataMatches, ...exactMatches, ...prefixMatches, ...containsMatches];
  const seen = new Set<string>();
  const deduped: WorldPlace[] = [];
  for (const item of results) {
    const key = item.slug;
    if (!seen.has(key)) {
      seen.add(key);
      deduped.push(item);
      if (deduped.length >= limit) break;
    }
  }

  return deduped;
}

export function getCountryFlagByName(name?: string): string | undefined {
  if (!name) return undefined;
  const n = name.trim().toLowerCase();
  const c = WORLD_COUNTRIES.find(
    (item) =>
      item.name.toLowerCase() === n ||
      item.officialName?.toLowerCase() === n ||
      item.iso2.toLowerCase() === n,
  );
  return c ? getFlagUrl(c.iso2) : undefined;
}
